async function verifySession(sessionToken) {
  if (!sessionToken)
    return null;
  try {
    const session = await auth.api.getSession({
      headers: {
        authorization: `Bearer ${sessionToken}`
      }
    });
    return session?.data || null;
  } catch (error53) {
    console.error("Session verification error:", error53);
    return null;
  }
}
async function createAuthContext2(req) {
  const authHeader = req.headers.authorization;
  const token = authHeader?.replace("Bearer ", "");
  const sessionCookie = req.cookies?.["better-auth.session"];
  const sessionToken = token || sessionCookie;
  const session = await verifySession(sessionToken);
  return {
    user: session?.user || null,
    session: session || null,
    isAuthenticated: !!session?.user,
    permissions: session?.user?.role === "ADMIN" ? ["admin"] : []
  };
}

